    ["Host: {1} · {2}"] = "Хозяин: {1} · {2}",
    ["Hosting only works on a regular account. This account is a game master account."] = "Создавать игры можно только с обычной учётной записи. Эта учётная запись — игровой мастер.",
    ["Huge fireball on elites and bosses"] = "Огромный огненный шар по элите и боссам",
